// #b0a2952d03da5f3e0446c91a — смена прав / блок / разблок / удаление участника пишутся в журнал доступа
// отдельными действиями (change_permission, block_user, unblock_user, remove_user). Кейс ACL-001.
// Две роли: business выполняет действия на /settings/users, admin проверяет /admin/access-log.
// ПРЕДУСЛОВИЕ (вручную, на каждый прогон): РАСХОДНЫЙ участник бизнеса общего business-аккаунта, уже вступивший
// и активный; его email — в .qa/accounts.env: QA_SPARE_MEMBER_EMAIL=… . Удаление необратимо: после теста участник
// «הוסר» и непригоден — для следующего прогона нужен новый. Общие business/user НЕ использовать. Не prod-safe.
import * as dotenv from 'dotenv';
import * as path from 'path';
import { Locator, Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

dotenv.config({ path: path.resolve(__dirname, '../../../accounts.env') });
const SPARE_EMAIL = process.env.QA_SPARE_MEMBER_EMAIL;
const ACTOR_EMAIL = process.env.QA_USER_BUSINESS_EMAIL;

type Entry = { action: string; actor_id: string; target_id: string | null; occurred_at: string; business_name: string };
type LogResponse = { entries: Entry[]; actors: { id: string; email: string | null }[] };

const LABELS: Record<string, string> = {
  change_permission: 'שינוי הרשאה של משתמש',
  block_user: 'חסימה של משתמש',
  unblock_user: 'ביטול חסימה של משתמש',
  remove_user: 'הסרה של משתמש',
};

/** Кнопка действия в строке; если открылось подтверждение — подтвердить. Ждём результат в строке. */
async function rowAction(page: Page, row: Locator, button: string, done: Locator) {
  await row.getByRole('button', { name: button, exact: true }).click();
  const dialog = page.getByRole('dialog').or(page.getByRole('alertdialog'));
  await expect(dialog.or(done).first()).toBeVisible();
  if (await dialog.isVisible()) {
    await dialog.getByRole('button', { name: new RegExp(`^(${button}|אישור)$`) }).click();
  }
  await expect(done).toBeVisible();
}

test.describe('Журнал доступа — отдельные действия по участнику (#b0a2952d03da5f3e0446c91a)', () => {
  test.skip(!SPARE_EMAIL, 'нет QA_SPARE_MEMBER_EMAIL в .qa/accounts.env — нужен новый расходный участник бизнеса');
  test.skip(!ACTOR_EMAIL, 'нет QA_USER_BUSINESS_EMAIL в .qa/accounts.env');

  test('смена прав → блок → разблок → удаление: change_permission, block_user, unblock_user, remove_user с метками на иврите @desktop @data #b0a2952d03da5f3e0446c91a', async ({ asUser }) => {
    const startedAt = Date.now() - 60_000; // запас на расхождение часов
    const business = await asUser('business');
    await business.goto('/settings/users');
    await expect(business.getByRole('heading', { level: 1, name: 'משתמשים והזמנות' })).toBeVisible();
    const row = business.getByRole('row').filter({ hasText: SPARE_EMAIL! });
    await expect(row, `расходный участник ${SPARE_EMAIL} не найден в /settings/users`).toHaveCount(1);
    await expect(row, 'расходный участник должен быть активен — после прошлого прогона нужен новый').toContainText('פעיל');
    test.info().annotations.push({ type: 'test-data', description: `участник ${SPARE_EMAIL} будет удалён (הוסר)` });

    // 1. Смена прав (кнопка «הפיכה ל…» меняется на противоположную).
    const permButton = row.getByRole('button', { name: /^הפיכה ל/ });
    const permName = (await permButton.innerText()).trim();
    const otherPerm = permName.includes('מגייס') ? 'הפיכה למנהל/ת חשבון' : 'הפיכה למנהל/ת מגייס/ת';
    await rowAction(business, row, permName, row.getByRole('button', { name: otherPerm, exact: true }));
    // 2. Блок → 3. разблок.
    await rowAction(business, row, 'חסימה', row.getByRole('button', { name: 'ביטול חסימה', exact: true }));
    await rowAction(business, row, 'ביטול חסימה', row.getByRole('button', { name: 'חסימה', exact: true }));
    // 4. Удаление — строка остаётся со статусом «הוסר», действий нет (FL-07).
    await rowAction(business, row, 'הסרה', row.getByText('הוסר', { exact: true }));
    await expect(row.getByRole('button')).toHaveCount(0);
    await expect(row).toContainText('—');

    // Журнал (admin): фильтр «משתמש» = исполнитель, «מתאריך» = сегодня → «סינון».
    const admin = await asUser('admin');
    const initial = admin.waitForResponse((r) => r.url().includes('/rpc/admin_list_access_log'));
    await admin.goto('/admin/access-log');
    await expect(admin.getByRole('heading', { level: 1, name: 'רישום גישה' })).toBeVisible();
    const { actors } = (await (await initial).json()) as LogResponse;
    const actor = actors.find((a) => a.email?.toLowerCase() === ACTOR_EMAIL!.toLowerCase());
    expect(actor, 'исполнитель business отсутствует в списке «משתמש»').toBeTruthy();

    const today = new Date().toLocaleDateString('en-CA'); // YYYY-MM-DD, локальная дата
    await admin.getByRole('combobox', { name: 'משתמש' }).selectOption({ value: actor!.id });
    await admin.getByLabel('מתאריך').fill(today);
    const filtered = admin.waitForResponse((r) => r.url().includes('/rpc/admin_list_access_log'));
    await admin.getByRole('button', { name: 'סינון', exact: true }).click();
    const res = await filtered;
    expect(res.ok()).toBeTruthy();
    const body = res.request().postDataJSON() as { p_actor_id: string | null; p_from: string | null };
    expect(body.p_actor_id).toBe(actor!.id);
    expect(body.p_from).toBeTruthy();
    const { entries } = (await res.json()) as LogResponse;

    // Целевой участник — тот, у кого за прогон есть remove_user (удаляется только он).
    const recent = entries.filter((e) => Date.parse(e.occurred_at) >= startedAt && e.actor_id === actor!.id);
    const removed = recent.filter((e) => e.action === 'remove_user');
    expect(removed, 'нет записи remove_user за прогон').toHaveLength(1);
    const targetId = removed[0].target_id;
    expect(targetId).toBeTruthy();
    const sequence = recent
      .filter((e) => e.target_id === targetId)
      .sort((a, b) => Date.parse(a.occurred_at) - Date.parse(b.occurred_at))
      .map((e) => e.action);
    // Источник: «מה רצוי» — «פעולות נפרדות remove_user ו-unblock_user» (не block_user / change_permission).
    expect(sequence).toEqual(['change_permission', 'block_user', 'unblock_user', 'remove_user']);
    expect(removed[0].business_name).toBe('testim');

    // Метки на иврите в таблице (без сырых ключей).
    const table = admin.getByRole('table');
    for (const label of Object.values(LABELS)) {
      await expect(table.getByRole('cell', { name: label, exact: true }).first()).toBeVisible();
    }
    for (const key of Object.keys(LABELS)) {
      await expect(table.getByText(key, { exact: true })).toHaveCount(0);
    }
  });
});
